import torch

def run(grad_output, input_ids, hidden_states_fp32, rstd, norm_weight):
    hidden_size = grad_output.shape[-1]
    grad_norm = grad_output.to(torch.float32) * norm_weight.to(torch.float32) / rstd.to(torch.float32)
    grad_norm_weight = (grad_output.to(torch.float32) * hidden_states_fp32).sum(dim=(0, 1))
    grad_embed_weight = torch.zeros(hidden_size, dtype=torch.bfloat16, device=grad_output.device)
    for i in range(input_ids.shape[0]):
        for j in range(input_ids.shape[1]):
            idx = input_ids[i, j].item()
            grad_embed_weight[idx] += grad_norm[i, j].sum()
    return grad_embed_weight.to(torch.bfloat16), grad_norm_weight.to(torch.bfloat16)
